// ─────────────────────────────────────────────────────────────────────────────

import * as jose from 'jose';
import bcrypt from 'bcryptjs';
import crypto from 'node:crypto';
import { cookies } from 'next/headers';
import { dbQuery, ensureUsersTable } from './db.js';

const USER_COOKIE_NAME = 'soulfull_user_session';
const JWT_EXPIRY = '7d';
const BCRYPT_ROUNDS = 12;

function getJwtSecret() {
  const secret = (process.env.JWT_SECRET || process.env.ADMIN_SESSION_SECRET || '').trim();
  if (!secret) throw new Error('JWT_SECRET env var is not configured');
  return secret;
}

// ─── Cookie Management ───────────────────────────────────────────────────────

export async function setUserCookie(token, maxAge = 60 * 60 * 24 * 7) {
  const cookieStore = await cookies();
  if (!token) {
    cookieStore.delete(USER_COOKIE_NAME);
  } else {
    cookieStore.set(USER_COOKIE_NAME, token, {
      httpOnly: true,
      maxAge,
      path: '/',
      sameSite: 'lax',
      secure: process.env.NODE_ENV === 'production',
    });
  }
}

// ─── JWT (Edge Compatible via jose) ──────────────────────────────────────────

export async function issueUserToken(userRow) {
  const secret = new TextEncoder().encode(getJwtSecret());
  const payload = {
    sub: userRow.id,
    email: userRow.email,
    name: userRow.name,
    role: userRow.role,
    permissionOverrides: userRow.permission_overrides
      ? JSON.parse(userRow.permission_overrides)
      : {},
  };

  return await new jose.SignJWT(payload)
    .setProtectedHeader({ alg: 'HS256' })
    .setIssuedAt()
    .setExpirationTime(JWT_EXPIRY)
    .sign(secret);
}

export async function decodeUserToken(token) {
  try {
    const secret = new TextEncoder().encode(getJwtSecret());
    const { payload } = await jose.jwtVerify(token, secret);
    return payload;
  } catch (err) {
    return null;
  }
}

// ─── Request Auth ────────────────────────────────────────────────────────────

export async function getUserFromCookies() {
  const cookieStore = await cookies();
  const token = cookieStore.get(USER_COOKIE_NAME)?.value;
  if (!token) return null;
  return await decodeUserToken(token);
}

/**
 * Strips sensitive fields before sending user object to client.
 */
export function sanitizeUser(row) {
  if (!row) return null;
  return {
    id: row.id,
    email: row.email,
    name: row.name,
    phone: row.phone || '',
    role: row.role,
    avatarUrl: row.avatar_url || null,
    isActive: row.is_active,
    createdAt: row.created_at,
  };
}

// ─── Password Logic (Node.js Only - use in API routes/Server Actions) ────────

export async function hashPassword(plaintext) {
  return bcrypt.hash(plaintext, BCRYPT_ROUNDS);
}

export async function verifyPassword(plaintext, hash) {
  return bcrypt.compare(plaintext, hash);
}
